import {GAME_TYPES,ANSWER_MODES,THEMES,uid,clone,esc,toInt,safeUrl,friendlyDate,createShow,demoShow,newGame,newSession,normalizeShow,fromMalagaBackup,showPublic} from './model.js';
import {localSync,cloudSync,cloudCreate,hasCloudConfig,cloudLogin,cloudLogout,saveCloudTemplate,loadCloudTemplates} from './sync.js';
const $=s=>document.querySelector(s), root=$('#app');
const params=new URLSearchParams(location.search), VIEW=['tv','player','host'].includes(params.get('view'))?params.get('view'):'host';
const SESSION_PARAM=(params.get('session')||'').replace(/[^A-Za-z0-9_-]/g,'').slice(0,30);
const LIVE_MODE=params.get('mode')==='cloud'?'cloud':'local';
const STORAGE_SHOWS='showstudio:v1:shows';
const STORE_ACTIVE='showstudio:v1:active';
const getJSON=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??f}catch{return f}};
let shows=getJSON(STORAGE_SHOWS,[]);
if(!Array.isArray(shows)||!shows.length){shows=[demoShow(),createShow('Meine erste Gameshow')];localStorage.setItem(STORAGE_SHOWS,JSON.stringify(shows));}
let showId=localStorage.getItem(STORE_ACTIVE)||shows[0]?.id;let view='dashboard',editorGameId=null,sidebar=true;
let session=null,bridge=null,sessionMode=LIVE_MODE,sessionId=SESSION_PARAM;
let publicState=null,members={},answers={},buzz=null,playerId='',playerName='',playerTeam='',cloudUser=null;
let loading=false,error='',toast='',toastTimer=null,showMediaHelp=false;
let lastAction='';let playerDraftName='',playerDraftAnswer='';const uiDraft={};
const currentShow=()=>shows.find(s=>s.id===showId)||shows[0];
const activeGame=()=>session?.showSnapshot?.games[session.gameIndex];
const question=()=>activeGame()?.questions[session.questionIndex]||null;
const currentTheme=()=>THEMES.find(t=>t.id===(session?.showSnapshot?.theme||currentShow()?.theme||publicState?.theme))||THEMES[0];
const link=(role)=>`${location.origin}${location.pathname}?view=${role}&session=${encodeURIComponent(session?.id||sessionId)}&mode=${sessionMode}`;
const icon=(s,cl='')=>`<span class="glyph ${cl}" aria-hidden="true">${esc(s)}</span>`;
const selected=(actual,expected)=>actual===expected?'selected':'';
const btn=(name,action,cl='secondary',data='')=>`<button type="button" class="btn ${cl}" data-act="${action}" ${data}>${name}</button>`;
const hint=(s)=>`<p class="hint">${s}</p>`;
const field=(title,id,value,kind='text',extra='')=>`<label class="field"><span>${esc(title)}</span><input id="${id}" type="${kind}" value="${esc(value)}" ${extra}></label>`;
const area=(title,id,value,extra='')=>`<label class="field"><span>${esc(title)}</span><textarea id="${id}" rows="3" ${extra}>${esc(value)}</textarea></label>`;
const opts=(items,value)=>items.map(([key,label])=>`<option value="${esc(key)}" ${selected(key,String(value))}>${esc(label)}</option>`).join('');
const selector=(title,id,items,value)=>`<label class="field"><span>${esc(title)}</span><select id="${id}">${opts(items,value)}</select></label>`;
const euro=n=>new Intl.NumberFormat('de-DE').format(n||0);
function saveShows(){localStorage.setItem(STORAGE_SHOWS,JSON.stringify(shows));}
function upsertShow(s){s.dateUpdated=Date.now();shows=shows.some(t=>t.id===s.id)?shows.map(t=>t.id===s.id?s:t):[s,...shows];saveShows();}
function openShow(id){showId=id;localStorage.setItem(STORE_ACTIVE,id);view='builder';editorGameId=null;render();}
function inform(message){toast=message;renderToast();clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast='';renderToast()},4200);}
function renderToast(){const node=$('#toast');if(node){node.textContent=toast;node.classList.toggle('visible',!!toast);}}
function flashError(e){error=String(e?.message||e);inform('⚠ '+error);console.warn('SHOWSTUDIO:',e);}
function download(name,contents,type='application/json'){const blob=new Blob([contents],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function themed(){const theme=currentTheme();document.documentElement.style.setProperty('--accent',theme.primary);document.documentElement.style.setProperty('--accent-two',theme.secondary);document.documentElement.style.setProperty('--studio-bg',theme.bg);}
function masthead(){return `<header class="topbar"><button class="logo" data-act="dashboard" aria-label="Zur Übersicht"><span class="logo-star">✦</span><span>SHOW<span class="logo-light">STUDIO</span><small>CREATE YOUR SHOW</small></span></button><div class="top-links"><span class="online-chip"><i></i> ${bridge?(sessionMode==='cloud'?'FIREBASE LIVE':'LOKALE VORSCHAU'):'SHOW BUILDER'}</span>${session?btn('◉ Regie','open-host','ghost'):''}${btn('MÁLAGA GAMES ↗','legacy','ghost')}</div></header>`;}
function side(){const items=[['dashboard','⌂','Übersicht'],['builder','▦','Show-Builder'],['library','◈','Spielbibliothek'],['sessions','▷','Spielstände'],['settings','⚙','Einstellungen']];return `<aside class="sidebar ${sidebar?'':'collapsed'}"><div class="side-heading">DEIN STUDIO</div>${items.map(([key,i,label])=>`<button class="side-link ${view===key?'active':''}" data-act="nav" data-target="${key}"><span>${i}</span>${label}</button>`).join('')}<div class="side-bottom"><div class="side-mini"><b>DEINE BÜHNE.</b><small>Deine Regeln. Deine Momente.</small></div><div class="version">BETA 1.0 · LOKAL & LIVE</div></div></aside>`;}
function shell(content){themed();root.innerHTML=`${masthead()}<div class="shell">${side()}<main class="main">${content}</main></div><div id="toast" class="toast" role="status"></div>`;renderToast();}
function heading(kicker,title,sub){return `<div class="page-heading"><div><div class="kicker">${kicker}</div><h1>${title}</h1><p>${sub}</p></div></div>`;}
function renderDashboard(){const html=`<section class="hero"><div class="hero-content"><span class="eyebrow">DEIN EIGENES TV-STUDIO</span><h1>Es ist <em>deine</em> Show.</h1><p>Wähle die Spiele, erfinde deine Regeln und hol deine Freunde auf die große Bühne. Alles an einem Ort.</p><div class="hero-actions">${btn('✦ Neue Show erstellen','create','primary large')}${btn('↗ Bestehende Show importieren','import-click','ghost light large')}</div><div class="hero-caption">Keine Installation · Läuft im Browser · Speicherung als Vorlage & JSON</div></div><div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="hero-star">✦</div><div class="hero-ribbon">IT'S SHOWTIME</div></div></section>
  <div class="section-head"><div><div class="kicker">SHOW-VERWALTUNG</div><h2>Deine Shows <span class="subcount">${shows.length}</span></h2></div>${btn('Neue Show +','create','secondary')}</div><div class="show-grid">${shows.map((s,i)=>`<article class="show-card" style="--show-color:${esc(THEMES.find(t=>t.id===s.theme)?.primary||'#ff728c')}"><div class="show-card-art"><div class="show-card-deco">✦</div><div class="mini-tag">SHOW ${String(i+1).padStart(2,'0')}</div><div class="show-card-title">${esc(s.name)}</div></div><div class="show-card-body"><p>${esc(s.subtitle||'Deine eigene Show')}</p><div class="meta"><span>◈ ${s.games.length} Spiele</span><span>◉ ${s.teams.length} Teams</span></div><div class="meta light">Zuletzt bearbeitet: ${friendlyDate(s.dateUpdated)}</div><div class="card-actions">${btn('Bearbeiten','edit-show','primary small',`data-id="${esc(s.id)}"`)}${btn('▷ Starten','start-choice','secondary small',`data-id="${esc(s.id)}"`)}${btn('···','show-menu','icon small',`data-id="${esc(s.id)}"`)}</div></div></article>`).join('')}</div>
  <div class="inspiration"><div>${icon('✦')}<b>Schon eine Show in MÁLAGA GAMES gebaut?</b><p>Du kannst deine alte JSON-Fragensicherung importieren. Die bisherige Live-Show bleibt dabei unverändert.</p></div>${btn('Alte Sicherung importieren','import-click','secondary')}</div>`;
 shell(html);}
function renderBuilder(){const s=currentShow();if(!s)return renderDashboard();const the=THEMES.find(t=>t.id===s.theme)||THEMES[0];const html=`${heading('SHOW-BUILDER / ${esc(s.name)}','Gestalte deine Show.','Alle Änderungen werden lokal gespeichert. Ein Export sichert deine Vorlage zusätzlich als Datei.')}
 <div class="builder-intro"><div class="builder-preview" style="--show-color:${the.primary}"><span class="preview-top">✦ LIVE SHOW CONCEPT</span><strong>${esc(s.name)}</strong><span>${esc(s.subtitle)}</span><div class="stage-bars"><i></i><i></i><i></i><i></i></div></div><div class="builder-summary"><b>${s.games.length} SPIELE</b><span>${s.teams.length} Teams · ${s.settings.coinsEnabled?'Münzen aktiv':'Ohne Münzen'}</span><div class="button-row">${btn('▷ Show starten','start-choice','primary')}${btn('⇩ Vorlage exportieren','export-show','secondary')}${btn('↻ Duplizieren','duplicate','ghost')}</div></div></div>
 <div class="tabs">${[['builder-overview','① Grundregeln'],['builder-games','② Spiele'],['builder-design','③ Design & Teams']].map(([t,l])=>`<button class="tab ${builderTab===t?'active':''}" data-act="tab" data-target="${t}">${l}</button>`).join('')}</div>
 ${builderTab==='builder-games'?gamesBuilder(s):builderTab==='builder-design'?designBuilder(s):rulesBuilder(s)}`;
 shell(html);}
let builderTab='builder-overview';
function rulesBuilder(s){return `<div class="panel"><div class="panel-head"><h2>Die Grundlagen</h2><p>Bestimme den Aufbau und die Wertung. Jedes Spiel kann eigene abweichende Regeln erhalten.</p></div><div class="form-grid">${field('Showname','show-name',s.name)}${field('Untertitel / Motto','show-subtitle',s.subtitle)}${selector('Gesamtwertung','score-mode',[['bonus','Nur Spielgewinne bringen Gesamtpunkte'],['direct','Alle erspielten Punkte zählen direkt'],['mixed','Spielpunkte + Siegbonus zählen']],s.settings.scoreMode)}${selector('Münzsystem','coins-mode',[['no','Deaktiviert'],['yes','Aktiviert: Münzen für Spiele / Antworten']],s.settings.coinsEnabled?'yes':'no')}${selector('Teilnehmerformat','participants-mode',[['teams','Teams'],['individual','Einzelspieler / Teams als Personen']],s.settings.participants)}</div>${hint('Änderungen werden gespeichert, sobald du ein Feld verlässt. Du kannst in jedem Spiel Punkte, Münzen, Antwortmodus und Frageanzahl separat festlegen.')}</div>
  <div class="feature-grid"><div class="mini-panel"><span class="feature-icon">◈</span><b>Spielregeln nach Maß</b><p>Punkte, Einsätze, Zeitlimit, Buzzer und Fragearten.</p></div><div class="mini-panel"><span class="feature-icon">✷</span><b>Gespeicherte Vorlagen</b><p>Eine Show beliebig oft spielen oder als Grundlage kopieren.</p></div><div class="mini-panel"><span class="feature-icon">◉</span><b>Live-Show</b><p>Regie, TV-Ansicht und freiwillige Handy-Eingaben.</p></div></div>`;}
function gamesBuilder(s){const game=editorGameId?s.games.find(g=>g.id===editorGameId):null;return `<div class="games-layout"><div><div class="section-head in-panel"><div><h2>Dein Spielplan</h2><p>Die Reihenfolge kannst du jederzeit ändern.</p></div>${btn('＋ Spiel hinzufügen','add-game-menu','primary small')}</div><div class="sortable-games">${s.games.map((g,i)=>`<div class="game-list-item ${g.id===editorGameId?'selected':''}"><div class="game-index">${String(i+1).padStart(2,'0')}</div><button class="game-select" data-act="game-edit" data-id="${esc(g.id)}"><strong>${esc(g.title)}</strong><span>${esc(GAME_TYPES[g.type]?.name||g.type)} · ${g.questions.length} Fragen · ${g.winPoints} Siegpunkte</span></button><div class="stacked-actions"><button title="Nach oben" ${i===0?'disabled':''} data-act="game-move" data-id="${g.id}" data-dir="-1">↑</button><button title="Nach unten" ${i===s.games.length-1?'disabled':''} data-act="game-move" data-id="${g.id}" data-dir="1">↓</button></div></div>`).join('')}</div>${btn('✦ Neues Spielmodul','add-game-menu','secondary block')}</div><div>${game?gameEditor(game):`<div class="empty-editor"><span>◈</span><h3>Wähle ein Spiel aus</h3><p>Bearbeite Spielregeln, Fragen, Punkte und Medien – oder lege ein neues Spielmodul an.</p>${btn('Erstes Spiel bearbeiten','game-edit','primary',`data-id="${s.games[0]?.id||''}"`)}</div>`}</div></div>`;}
function gameEditor(g){const mod=GAME_TYPES[g.type]||GAME_TYPES.quiz;return `<div class="panel editor-panel"><div class="editor-header"><div><span class="eyebrow">${esc(mod.icon)} SPIELMODUL · ${esc(mod.name)}</span><h2>${esc(g.title)}</h2></div>${btn('Löschen','game-remove','danger small',`data-id="${g.id}"`)}</div><div class="form-grid">${field('Spielname','game-title',g.title)}${selector('Modultyp','game-type',Object.entries(GAME_TYPES).map(([k,v])=>[k,v.name]),g.type)}${field('Siegpunkte für dieses Spiel','game-winpoints',g.winPoints,'number','min="0" max="9999"')}${selector('Wertungsmodus','game-scoremode',[['inherit','Von Show übernehmen'],['bonus','Nur Siegbonus'],['direct','Jeder Spielpunkt zählt'],['mixed','Spielpunkte + Siegbonus']],g.scoreMode)}${selector('Antwortmodus','game-answer',Object.entries(ANSWER_MODES),g.answerMode)}${field('Zeitlimit pro Frage (Sek.; 0 = aus)','game-seconds',g.seconds,'number','min="0" max="3600"')}${field('Punkte für richtige Antwort','game-correct',g.correctPoints,'number','min="0"')}${field('Abzug für falsche Antwort','game-wrong',g.wrongPoints,'number','min="0"')}${field('Münzen pro richtige Antwort','game-coin-correct',g.coinCorrect,'number','min="0"')}${field('Münzen für Spielgewinn','game-coin-win',g.coinWin,'number','min="0"')}</div>${area('Moderator-Notizen & Spielregeln','game-description',g.description)}
 ${g.type==='estimate'?field('Abweichungseinheit (z. B. 10 Meter)','game-tolerance',g.estimateTolerance,'number','min="0.0001" step="any"'):''}
 ${g.type==='wager'?field('Zusätzlicher Einsatzbonus','game-wagerbonus',g.wagerBonus,'number','min="0"'):''}
 ${g.type==='collection'?area('Sammelkategorien (eine pro Zeile)','game-collections',g.collectionNames.join('\n')):''}
 <label class="check-field"><input type="checkbox" id="game-show-responses" ${g.showResponses?'checked':''}> Teilnehmenden-Eingaben dürfen vom Moderator auf dem Fernseher eingeblendet werden</label>
 <div class="editor-divider"></div><div class="section-head in-panel"><div><h3>Fragen & Aufgaben</h3><p>${g.questions.length} Einträge · optional mit Bild, Audio oder Video per URL</p></div>${btn('＋ Frage','question-add','secondary small',`data-id="${g.id}"`)}</div>
 ${g.questions.map((q,i)=>`<div class="question-editor"><div class="question-head"><b>FRAGE ${String(i+1).padStart(2,'0')}</b>${btn('×','question-delete','tiny danger',`data-q="${q.id}"`)}</div>${area('Frage oder Aufgabe',`q-text-${q.id}`,q.text)}${field('Lösung / Moderationsnotiz',`q-answer-${q.id}`,q.answer)}${g.type==='choice'||g.type==='wager'?area('Antwortmöglichkeiten (eine pro Zeile)',`q-options-${q.id}`,(q.options||[]).join('\n')):''}<div class="form-grid">${selector('Medium',`q-media-type-${q.id}`,[['','Ohne Medium'],['image','Bild'],['audio','Audio'],['video','Video']],q.mediaType)}${field('Medien-URL (HTTPS)',`q-media-${q.id}`,q.mediaUrl,'url','placeholder="https://..."')}</div></div>`).join('')}${btn('＋ Weitere Frage hinzufügen','question-add','ghost block',`data-id="${g.id}"`)}</div>`;}
function designBuilder(s){return `<div class="panel"><div class="panel-head"><h2>Die Bühne gehört dir</h2><p>Verändere das Farbthema und die Teams deiner Show.</p></div><div class="kicker">FARBSCHWELLE / THEME</div><div class="theme-grid">${THEMES.map(t=>`<button class="theme-card ${t.id===s.theme?'chosen':''}" data-act="theme-set" data-id="${t.id}"><span class="theme-wash" style="--c1:${t.primary};--c2:${t.secondary}">✦</span><b>${t.name}</b><span>${t.id===s.theme?'✓ Aktives Design':'Auswählen'}</span></button>`).join('')}</div><div class="section-head in-panel"><h3>Teams / Einzelspieler</h3>${btn('+ Team hinzufügen','team-add','secondary small')}</div><div class="team-edit-list">${s.teams.map((t,i)=>`<div class="team-edit"><span class="team-pip" style="background:${esc(t.color)}"></span>${field('Team '+(i+1),`team-name-${t.id}`,t.name)}<label class="field color-label"><span>Farbe</span><input type="color" id="team-color-${t.id}" value="${esc(t.color)}"></label>${s.teams.length>2?btn('×','team-remove','tiny danger',`data-id="${t.id}"`):''}</div>`).join('')}</div>${hint('Bis zu sechs Teams sind möglich. Für Einzelspieler kannst du eine eigene „Team“-Zeile pro Person verwenden.')}</div>`;}
function renderLibrary(){shell(`${heading('SPIELBIBLIOTHEK','Eine Show. Unendlich viele Ideen.','Diese sieben Spielmodule bilden die Grundlage deines Baukastens. Weitere spezielle Mechaniken können ergänzt werden.')}<div class="module-grid">${Object.entries(GAME_TYPES).map(([key,m])=>`<article class="module-card"><span class="module-symbol">${esc(m.icon)}</span><h3>${esc(m.name)}</h3><p>${esc(m.desc)}</p>${btn('+ Zur Show hinzufügen','quick-module','secondary small',`data-type="${key}"`)}</article>`).join('')}</div>`);}
function renderSessions(){const keys=Object.keys(localStorage).filter(k=>k.startsWith('showstudio:v1:session:')),stored=keys.map(k=>getJSON(k,null)).filter(Boolean);shell(`${heading('FORTSETZEN','Deine Spielstände','Lokale Show-Spielstände bleiben in diesem Browser erhalten. Cloud-Shows kannst du mit ihrer Kennung öffnen.')}<div class="panel">${stored.length?stored.map(s=>`<div class="resume-item"><div><b>${esc(s.showSnapshot?.name||'Gameshow')}</b><small>${esc(s.id)} · ${friendlyDate(s.updated)} · Spiel ${s.gameIndex+1}</small></div><div class="button-row">${btn('Fortsetzen','resume-session','primary small',`data-id="${s.id}"`)}${btn('Entfernen','delete-session','danger small',`data-id="${s.id}"`)}</div></div>`).join(''):'<div class="empty-list">Noch kein lokaler Spielstand. Starte deine erste Show!</div>'}<div class="editor-divider"></div>${field('Bestehende Cloud-Show-ID öffnen','cloud-room','', 'text','placeholder="z. B. X5GHY2"')}<div class="button-row">${btn('Cloud-Regie öffnen','cloud-resume','secondary')}${btn('Als TV öffnen','cloud-tv','ghost')}</div></div>`);}
function renderSettings(){shell(`${heading('STUDIO-SETTINGS','Alles unter Kontrolle.','Speicherung, Online-Verbindung und Datensicherung.')}<div class="panel"><h2>Deine Vorlagen</h2><p>Alle Shows sind lokal im Browser gespeichert. Sichere sie zusätzlich als JSON-Dateien, damit du sie auf andere Computer übertragen kannst.</p><div class="button-row">${btn('Alle Vorlagen exportieren','export-all','secondary')}${btn('JSON importieren','import-click','ghost')}</div></div><div class="panel"><h2>Firebase-Live-Verbindung</h2><div class="status-line"><span class="status-dot ${hasCloudConfig()?'on':''}"></span>${hasCloudConfig()?'Firebase-Konfiguration gefunden':'Noch keine Firebase-Konfiguration hinterlegt'}</div><p>TV und Handys können im lokalen Modus in mehreren Tabs desselben Browsers testen. Für mehrere Geräte brauchst du die Firebase-Verbindung und die mitgelieferten Sicherheitsregeln.</p><div class="button-row">${btn('Moderator anmelden','cloud-login-view','primary')}${btn('Vorlagen in Firebase sichern','cloud-save-all','secondary')}${btn('Vorlagen aus Firebase laden','cloud-load-all','ghost')}</div>${hint('Sicherheitsregeln im bestehenden Firebase-Projekt ergänzen, nicht die bisherige MÁLAGA-GAMES-Regeldatei überschreiben. Für Live-Hosting ist eine E-Mail/Passwort-Anmeldung erforderlich.')}</div><div class="panel"><h2>Deine bisherige MÁLAGA GAMES</h2><p>Die alte, funktionierende App wird durch SHOWSTUDIO nicht verändert. Eigene Fragen können über die bisherige JSON-Sicherung importiert werden.</p>${btn('Alte Show öffnen ↗','legacy','secondary')}</div>`);}
function renderLogin(){shell(`<div class="auth-layout"><div class="auth-card"><span class="module-symbol">◉</span><h1>Regie anmelden</h1><p>Für die Cloud-Live-Show brauchst du deinen bestehenden Moderatorzugang aus Firebase Authentication.</p>${field('Moderator-E-Mail','auth-email','', 'email','autocomplete="email"')}${field('Passwort','auth-password','', 'password','autocomplete="current-password"')}<div class="button-row">${btn('Mit Firebase anmelden','cloud-login','primary')}${btn('Zurück','dashboard','ghost')}</div>${hint('Wenn noch keine Firebase-Konfiguration vorliegt, kannst du die Show im lokalen Modus ausprobieren. Nie Passwörter in GitHub-Dateien eintragen.')}</div></div>`);}
function renderStartChoice(){const s=currentShow();shell(`<div class="choice-layout">${heading('BACKSTAGE','Bereit für den großen Auftritt?','Wie möchtest du '+esc(s.name)+' starten?')}<div class="start-options"><article class="start-box"><div class="start-icon">⌂</div><h2>Lokal testen</h2><p>Ohne Anmeldung. Ideal für die Entwicklung und für Regie und TV im selben Browser.</p>${btn('Lokal starten','start-local','primary block')}</article><article class="start-box live"><div class="start-icon">◉</div><h2>Live mit Firebase</h2><p>Mit echten Smartphones, synchronisierten Buzzern und einer unabhängigen TV-Ansicht.</p>${btn('Online starten','start-cloud','secondary block')}${hint(hasCloudConfig()?'Firebase eingerichtet. Moderatorzugang erforderlich.':'Bitte zunächst firebase-config.js ausfüllen und Regeln ergänzen.')}</article></div></div>`);}
function renderAddGame(){shell(`<div class="choice-layout">${heading('NEUES SPIEL','Wähle die Spielart.','Du kannst Spielname, Wertung und Antwortmodus danach frei verändern.')}<div class="module-grid">${Object.entries(GAME_TYPES).map(([key,m])=>`<button class="module-card clickable" data-act="add-module" data-type="${key}"><span class="module-symbol">${esc(m.icon)}</span><h3>${esc(m.name)}</h3><p>${esc(m.desc)}</p><span class="select-module">+ Hinzufügen</span></button>`).join('')}</div>${btn('← Zur Show','builder-games-back','ghost')}</div>`);}
function teamName(id,which){const s=which||session?.showSnapshot;return s?.teams.find(t=>t.id===id)?.name||id;}
function scoreboardHTML(scoreboard,teams,coinsEnabled,gameScores=null){return `<div class="score-grid">${teams.map(t=>{const s=scoreboard?.[t.id]||{points:0,coins:0};return `<div class="score-team" style="--team:${esc(t.color)}"><div class="team-identity"><span class="dot"></span>${esc(t.name)}</div><div class="big-score">${euro(s.points)}</div><small>GESAMTPUNKTE</small>${gameScores?`<div class="score-foot"><span>Spielpunkte: <b>${euro(gameScores[t.id])}</b></span>${coinsEnabled?`<span>◉ ${euro(s.coins)} Münzen</span>`:''}</div>`:coinsEnabled?`<div class="score-foot">◉ ${euro(s.coins)} Münzen</div>`:''}</div>`;}).join('')}</div>`;}
function renderHost(){if(!session){root.innerHTML=`${masthead()}<div class="boot-center">${icon('◈')}<h2>Spielstand wird geladen …</h2>${btn('Zur Startseite','dashboard','secondary')}</div><div id="toast" class="toast"></div>`;return;}
 const s=session.showSnapshot,g=activeGame(),q=question(),res=Object.entries(answers).filter(([,v])=>v.questionToken===session.questionToken), mode=g?.scoreMode==='inherit'?s.settings.scoreMode:g?.scoreMode;
 const html=`<div class="host-head"><div><span class="eyebrow">◉ REGIEPULT · ${sessionMode==='cloud'?'FIREBASE LIVE':'LOKAL'}</span><h1>${esc(s.name)}</h1><p>Raumcode <b>${esc(session.id)}</b> · ${s.games.length} Spiele · ${Object.keys(members).length} Spieler verbunden</p></div><div class="button-row">${btn('◧ TV öffnen','tv-open','secondary')}${btn('▣ Handy-Link','player-link','secondary')}${btn('⇩ Spielstand','session-export','ghost')}${btn('↶ Rückgängig','undo','ghost')}</div></div>
 ${scoreboardHTML(session.scoreboard,s.teams,s.settings.coinsEnabled,session.gameScores)}<div class="game-progress"><div class="game-progress-track">${s.games.map((x,i)=>`<button class="progress-step ${i===session.gameIndex?'here':''} ${session.results[x.id]!==undefined?'done':''}" data-act="goto-game" data-index="${i}" title="${esc(x.title)}">${i+1}</button>`).join('')}</div><div class="game-progress-foot"><span>Spiel ${session.gameIndex+1} von ${s.games.length}</span><span>${esc(g?.title||'')}</span></div></div>
 <div class="host-columns"><div class="host-main"><div class="panel play-panel"><div class="stage-head"><span class="eyebrow">SPIEL ${session.gameIndex+1} / ${s.games.length} · ${esc(GAME_TYPES[g?.type]?.name||'')}</span><span class="phase-chip">${{lobby:'VORBEREITUNG',game:'LIVE',break:'ZWISCHENSTAND',end:'SHOW-ENDE'}[session.phase]||'REGIE'}</span></div><h2>${esc(g?.title||'')}</h2><p>${esc(g?.description||'')}</p><div class="game-status"><span>🏆 ${g?.winPoints||0} Siegpunkte</span><span>◎ ${g?.questions.length||0} Fragen</span><span>◉ ${esc(ANSWER_MODES[g?.answerMode]||'Moderator')}</span><span>⏱ ${g?.seconds||0}s</span></div>
 ${session.phase==='lobby'?`<div class="start-center">${btn('▶ Show beginnen','start-game','primary large')}</div>`:session.phase==='break'?`<div class="big-announcement">${esc(session.roundMessage||'Zwischenstand')}<span>Weiter geht's!</span></div><div class="button-row">${btn('Nächstes Spiel ▶','next-game','primary')}${btn('Wertung korrigieren','undo','ghost')}</div>`:session.phase==='end'?`<div class="big-announcement">✦ SHOW ENDE <span>${esc(session.roundMessage||'Das war eure Show!')}</span></div>`:
 `<div class="current-question"><div class="question-top">FRAGE ${session.questionIndex+1} / ${g?.questions.length||0}</div><h3>${esc(q?.text||'Keine Frage hinterlegt – bei einer Challenge kannst du die Wertung trotzdem manuell vergeben.')}</h3>${mediaHTML(q?.mediaType,q?.mediaUrl)}${g?.type==='choice'||g?.type==='wager'?`<div class="option-grid">${(q?.options||[]).map((opt,i)=>`<div class="option"><b>${'ABCDEF'[i]}</b>${esc(opt)}</div>`).join('')}</div>`:''}${session.revealed?`<div class="answer-box">✓ Lösung: <b>${esc(q?.answer||'Keine Lösung hinterlegt')}</b></div>`:''}</div>
 <div class="button-row main-controls">${btn(session.revealed?'Lösung sichtbar':'✓ Lösung aufdecken','reveal','primary')}${btn('◉ Buzzer '+(session.buzzOpen?'schließen':'öffnen'),'buzz-toggle',session.buzzOpen?'secondary':'outline')}${btn('⌨ Eingaben '+(session.entryOpen?'schließen':'öffnen'),'entry-toggle','outline')}${btn('→ Nächste Frage','next-question','secondary')}</div><div class="response-area"><div><h3>Antworten & Buzzer</h3>${buzz?`<div class="buzzer-winner">⚡ ${esc(buzz.name)} – ${esc(teamName(buzz.teamId,s))} hat gebuzzert!</div>`:hint('Noch niemand hat gebuzzert.')}${btn('Buzzer zurücksetzen','buzz-clear','ghost small')}</div><div><b>${res.length} Handy-Antworten</b>${res.map(([pid,a])=>`<div class="submission"><strong>${esc(members[pid]?.name||'Spieler')} · ${esc(teamName(a.teamId,s))}</strong><span>${esc(a.value)}</span>${g?.showResponses?btn('Auf TV zeigen','response-display','tiny secondary',`data-value="${encodeURIComponent(a.value).slice(0,2000)}"`):''}</div>`).join('')}${btn('Eingaben löschen','answers-clear','ghost small')}</div></div>`}
 </div>${session.phase==='game'?`<div class="panel"><div class="section-head in-panel"><div><h3>Wertung & Münzen</h3><p>${mode==='bonus'?'Nur der Kategoriesieg zählt für die Gesamtwertung.':mode==='direct'?'Jeder Spielpunkt fließt in den Gesamtstand.':'Spielpunkte zählen direkt, zusätzlich gibt es Siegpunkte.'}</p></div></div>${g?.type==='estimate'?estimateControls(g,q):g?.type==='collection'?collectionControls(g):g?.type==='wager'?wagerControls(g):''}<div class="score-action-grid">${s.teams.map(t=>`<div class="score-action" style="--team:${esc(t.color)}"><b><span class="dot"></span> ${esc(t.name)}</b><small>${session.gameScores[t.id]||0} Spielpunkte</small><div class="button-row">${btn('+ Richtig','score-correct','secondary small',`data-team="${t.id}"`)}${btn('− Falsch','score-wrong','ghost small',`data-team="${t.id}"`)}</div><div class="button-row">${btn('+ Punkt','score-plus','ghost small',`data-team="${t.id}"`)}${btn('− Punkt','score-minus','ghost small',`data-team="${t.id}"`)}${s.settings.coinsEnabled?btn('+ Münze','coin-plus','ghost small',`data-team="${t.id}"`):''}</div>${btn('🏆 Spiel gewonnen','game-win','primary small block',`data-team="${t.id}"`)}</div>`).join('')}</div><div class="button-row">${btn('Ohne Sieger beenden','game-draw','ghost')}${btn('Spiel abbrechen','game-cancel','danger')}</div></div>`:''}</div><div class="host-rail"><div class="panel"><h3>Show-Navigation</h3>${s.games.map((sg,i)=>`<button class="rail-game ${i===session.gameIndex?'current':''}" data-act="goto-game" data-index="${i}"><span>${i+1}</span><b>${esc(sg.title)}</b><small>${sg.winPoints} P.</small></button>`).join('')}</div><div class="panel links"><h3>Deine Live-Links</h3><p>Öffne den TV-Link auf dem Fernseher und teile den Handy-Link mit den Spielern.</p>${field('TV-Link','readonly-tv',link('tv'),'text','readonly')}${btn('TV-Link kopieren','copy-tv','secondary small block')}${field('Spieler-Link','readonly-player',link('player'),'text','readonly')}${btn('Handy-Link kopieren','copy-player','secondary small block')}${sessionMode==='local'?hint('Im lokalen Modus können andere Geräte nicht auf diesen Spielstand zugreifen. Für Smartphones aus dem WLAN: Firebase Live wählen.'):''}</div></div></div>`;
 themed();root.innerHTML=`${masthead()}<main class="host-layout">${html}</main><div id="toast" class="toast" role="status"></div>`;renderToast();}
function mediaHTML(type,url){const src=safeUrl(url);if(!src||!type)return '';if(type==='image')return `<img class="question-media" src="${esc(src)}" alt="Bild zur Frage" loading="lazy">`;if(type==='audio')return `<audio class="media-player" controls src="${esc(src)}"></audio>`;if(type==='video')return `<video class="media-player" controls playsinline src="${esc(src)}"></video>`;return '';}
function estimateControls(g,q){return `<div class="special-control"><h4>≋ Schätzung auswerten</h4>${field('Richtiger Wert','estimate-correct',uiDraft['estimate-correct']??q?.answer??0,'number','step="any"')}<div class="form-grid">${session.showSnapshot.teams.map(t=>field(t.name+' · Schätzung','estimate-'+t.id,uiDraft['estimate-'+t.id]??'','number','step="any"')).join('')}</div>${btn('Abweichungen vergleichen & Punkt vergeben','estimate-score','secondary block')}</div>`;}
function collectionControls(g){return `<div class="special-control"><h4>✷ Sammelkategorien</h4>${session.showSnapshot.teams.map(t=>`<div class="collection-team"><b>${esc(t.name)}</b><div class="collection-pills">${g.collectionNames.map(cat=>{const owned=(session.collected?.[t.id]||[]).includes(cat);return `<button class="collection-pill ${owned?'owned':''}" data-act="collection-toggle" data-team="${t.id}" data-category="${esc(cat)}">${owned?'✓ ':'＋ '}${esc(cat)}</button>`}).join('')}</div></div>`).join('')}</div>`;}
function wagerControls(g){const banks=session.banks||{};return `<div class="special-control"><h4>◆ Separates Einsatzkonto</h4><p>Die Einsätze verändern die Gesamtpunkte nicht. Nur der Kategoriesieg bringt die festgelegten Siegpunkte.</p><div class="wager-teams">${session.showSnapshot.teams.map(t=>`<div><strong>${esc(t.name)}: ${euro(banks[t.id]??0)} Einsatzpunkte</strong><div class="form-grid four">${[0,1,2,3].map(i=>field('Antwort '+('ABCD'[i]),`wager-${t.id}-${i}`,uiDraft[`wager-${t.id}-${i}`]??session.allocations?.[t.id]?.[i]??0,'number','min="0"')).join('')}</div></div>`).join('')}</div>${btn('Alle Einsätze auswerten','wager-score','secondary block')}</div>`;}
function publicForView(){if(publicState)return publicState;if(session)return showPublic(session,session.showSnapshot);return null;}
function renderTV(){const p=publicForView();if(!p){root.innerHTML=`<div class="tv-screen"><div class="tv-empty"><span>✦</span><h1>SHOWSTUDIO</h1><p>Warte auf die Regie …</p></div></div>`;return;}
 const teams=p.teams||[];const colors=THEMES.find(t=>t.id===p.theme)||THEMES[0];document.documentElement.style.setProperty('--accent',colors.primary);document.documentElement.style.setProperty('--accent-two',colors.secondary);
 root.innerHTML=`<div class="tv-screen"><header class="tv-top"><div class="tv-brand">✦ SHOW<span>STUDIO</span></div><span>THE SHOW IS YOURS.</span></header><section class="tv-show-label"><div class="eyebrow">${p.phase==='break'?'ZWISCHENSTAND':p.phase==='end'?'FINALER PUNKTESPIEGEL':`SPIEL ${(p.gameIndex||0)+1}`}</div><h1>${esc(p.phase==='game'?p.gameTitle:p.showName)}</h1><p>${esc(p.phase==='game'?p.showName:p.subtitle)}</p></section><div class="tv-score-grid">${teams.map(t=>`<div class="tv-score" style="--team:${esc(t.color)}"><span>${esc(t.name)}</span><b>${euro(p.scoreboard?.[t.id]?.points)}</b><small>GESAMTPUNKTE${p.coinsEnabled?` · ◉ ${euro(p.scoreboard?.[t.id]?.coins)} MÜNZEN`:''}</small>${p.phase==='game'?`<div class="tv-game-score">${euro(p.gameScores?.[t.id])} <span>SPIELPUNKTE</span></div>`:''}</div>`).join('')}</div><section class="tv-prompt">${p.phase==='game'?`<div class="eyebrow">FRAGE ${(p.questionIndex||0)+1} / ${p.questionTotal||0}</div><h2>${esc(p.prompt||'Die nächste Aufgabe beginnt gleich …')}</h2>${mediaHTML(p.mediaType,p.mediaUrl)}${p.options?.length?`<div class="tv-options">${p.options.map((v,i)=>`<div><span>${'ABCDEF'[i]}</span>${esc(v)}</div>`).join('')}</div>`:''}${p.answerRevealed?`<div class="tv-reveal">✓ ${esc(p.answer)}</div>`:''}${p.roundMessage?`<div class="tv-message">${esc(p.roundMessage)}</div>`:''}${p.gameType==='collection'?`<div class="tv-collections">${teams.map(t=>`<div><b>${esc(t.name)}:</b> ${(p.collected?.[t.id]||[]).map(esc).join(' · ')||'Noch keine Karte'}</div>`).join('')}</div>`:''}${p.gameType==='wager'?`<div class="tv-collections">${teams.map(t=>`<div><b>${esc(t.name)}: </b>${euro(p.wagerBanks?.[t.id]||0)} Einsatzpunkte</div>`).join('')}</div>`:''}`:`<div class="tv-intermission">${p.phase==='lobby'?'Gleich geht’s los!':p.phase==='end'?'Danke fürs Mitspielen!':esc(p.roundMessage||'Bereit für die nächste Runde?')}</div>`}</section><footer class="tv-footer"><div class="tv-progress">${Array.from({length:Math.max(1,(p.resultsTotal||0)||1)},()=>'<i></i>').join('')}</div><span>${esc(p.showName)}</span></footer></div>`;}
function renderPlayer(){const p=publicForView();if(!p){root.innerHTML=`<div class="player-layout"><div class="player-card"><span class="module-symbol">✦</span><h1>SHOWSTUDIO</h1><p>Verbindung zur Show wird hergestellt …</p></div></div>`;return;}
 const teams=p.teams||[],joined=!!playerId;
 root.innerHTML=`<div class="player-layout"><div class="player-top">✦ SHOW<span>STUDIO</span></div><div class="player-card"><div class="eyebrow">LIVE MIT DABEI</div><h1>${esc(p.showName)}</h1><p>${esc(p.phase==='game'?p.gameTitle:p.subtitle||'')}</p>${!joined?`<div class="player-join">${field('Dein Name','join-name',playerDraftName||playerName,'text','maxlength="60" placeholder="Vorname"')}${selector('Dein Team','join-team',teams.map(t=>[t.id,t.name]),playerTeam||teams[0]?.id)}${btn('Der Show beitreten →','player-join','primary block')}</div>`:
 `<div class="player-belong">✓ ${esc(playerName)} · ${esc(teams.find(t=>t.id===playerTeam)?.name||'')}</div>${p.phase==='game'?`<div class="player-question"><span>FRAGE ${(p.questionIndex||0)+1}</span><h2>${esc(p.prompt||'')}</h2>${p.options?.length?`<div class="player-options">${p.options.map((v,i)=>`<button class="player-option" ${!p.entryOpen?'disabled':''} data-act="player-option" data-value="${esc('ABCDEF'[i])}"><b>${'ABCDEF'[i]}</b>${esc(v)}</button>`).join('')}</div>`:''}${p.answerRevealed?`<div class="answer-box">✓ ${esc(p.answer)}</div>`:''}</div>${['buzz','both'].includes(p.answerMode)?(p.buzzOpen?btn('⚡ BUZZER','player-buzz','buzzer block large'):btn('Buzzer geschlossen','player-buzz','buzzer block large', 'disabled')):''}${p.entryOpen&&['text','both'].includes(p.answerMode)?`<div class="player-entry">${field('Deine Antwort','player-answer',playerDraftAnswer,'text','placeholder="Antwort eingeben"')}${btn('Antwort senden','player-send','secondary block')}</div>`:''}`:`<div class="player-wait">✦<h2>${p.phase==='end'?'Die Show ist vorbei.':'Gleich geht es weiter!'}</h2><p>Du bist verbunden. Deine Regie sagt dir, wann du an der Reihe bist.</p></div>`}`}</div><div class="player-footer">SHOWSTUDIO · LIVE PARTICIPANT</div><div id="toast" class="toast"></div></div>`;renderToast();}
function render(){if(VIEW==='tv')return renderTV();if(VIEW==='player')return renderPlayer();if(view==='host')return renderHost();if(view==='builder')return renderBuilder();if(view==='library')return renderLibrary();if(view==='settings')return renderSettings();if(view==='sessions')return renderSessions();if(view==='login')return renderLogin();if(view==='start-choice')return renderStartChoice();if(view==='add-game')return renderAddGame();return renderDashboard();}
function record(){if(!session)return;const snapshot=clone({...session,history:[]});session.history=(session.history||[]).slice(-14);session.history.push(snapshot);}
async function persist(){if(!session||!bridge)return;session.updated=Date.now();try{await bridge.hostSave(session,showPublic(session,session.showSnapshot));}catch(ex){flashError(ex)}render();}
function mutate(fn){record();fn();return persist();}
async function connectSession(id,mode,role){bridge?.close();sessionId=id;sessionMode=mode;members={};answers={};buzz=null;publicState=null;
 if(mode==='local'){
  bridge=localSync(id,events=>{
   if(events.session){if(role==='host')session=events.session;publicState=showPublic(events.session,events.session.showSnapshot);}
   if(events.members)members=events.members;if(events.answers)answers=events.answers; if('buzz'in events)buzz=events.buzz;
   render();});bridge.read();
 }else{
  bridge=await cloudSync(id,role,ev=>{
   if(ev.error){flashError(new Error(ev.error));return;}if('session'in ev&&role==='host'&&ev.session)session=ev.session;
   if('public'in ev)publicState=ev.public;
   if('members'in ev)members=ev.members||{};
   if('answers'in ev)answers=ev.answers||{};
   if('buzz'in ev)buzz=ev.buzz;
   render();
  });
 }
}
async function beginSession(mode){const s=currentShow();const next=newSession(s);session=next;sessionMode=mode;sessionId=next.id;
 if(mode==='cloud'){if(!hasCloudConfig())throw Error('Bitte zuerst Firebase konfigurieren. Alternativ lokal testen.');await cloudCreate(next,showPublic(next,s));}
 await connectSession(next.id,mode,'host');await bridge.hostSave(next,showPublic(next,s));view='host';history.replaceState({},'',`?view=host&session=${next.id}&mode=${mode}`);render();}
function startGame(){return mutate(()=>{session.phase='game';session.gameScores=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,0]));session.questionIndex=0;session.questionToken=uid();session.revealed=false;session.roundMessage='';session.buzzOpen=false;session.entryOpen=false;const g=activeGame();if(g?.type==='wager'){session.banks=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,session.scoreboard[t.id].points+toInt(g.wagerBonus)]));session.allocations=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,[0,0,0,0]]));}});}
function nextQuestion(){const g=activeGame();if(!g)return;if(session.questionIndex+1>=g.questions.length){inform('Keine weitere Frage hinterlegt. Du kannst jetzt den Gewinner festlegen oder das Spiel beenden.');return;}return mutate(()=>{session.questionIndex++;session.questionToken=uid();playerDraftAnswer='';for(const k of Object.keys(uiDraft))delete uiDraft[k];session.revealed=false;session.roundMessage='';session.buzzOpen=false;session.entryOpen=false;session.showMediaAnswer='';session.allocations=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,[0,0,0,0]]));}).then(()=>{bridge?.clearBuzz();bridge?.clearAnswers();});}
function valueScore(teamId,delta,kind='regular'){
 return mutate(()=>{const g=activeGame();let mode=g.scoreMode==='inherit'?session.showSnapshot.settings.scoreMode:g.scoreMode;const val=session.gameScores[teamId]||0;
 session.gameScores[teamId]=Math.max(0,val+delta);
 if(mode==='direct'||mode==='mixed'){session.scoreboard[teamId].points=Math.max(0,session.scoreboard[teamId].points+delta);}
 if(delta>0&&kind==='correct'&&session.showSnapshot.settings.coinsEnabled)session.scoreboard[teamId].coins+=g.coinCorrect||0;
 });
}
function finishGame(teamId){return mutate(()=>{const g=activeGame();if(session.results[g.id]!==undefined)return;const mode=g.scoreMode==='inherit'?session.showSnapshot.settings.scoreMode:g.scoreMode;
 if(teamId&&mode!=='direct'){session.scoreboard[teamId].points+=(g.winPoints||0);}
 if(teamId&&session.showSnapshot.settings.coinsEnabled)session.scoreboard[teamId].coins+=(g.coinWin||0);
 session.results[g.id]=teamId||'draw';session.phase='break';session.roundMessage=teamId?teamName(teamId,session.showSnapshot)+' gewinnt '+g.title+'!':'Dieses Spiel endet ohne Sieger.';session.buzzOpen=false;session.entryOpen=false;
 });}
function advanceGame(){return mutate(()=>{if(session.gameIndex+1>=session.showSnapshot.games.length){session.phase='end';session.roundMessage='Alle Spiele abgeschlossen';return;}session.gameIndex++;session.questionIndex=0;session.questionToken=uid();session.phase='lobby';session.roundMessage='';session.revealed=false;session.buzzOpen=false;session.entryOpen=false;session.gameScores=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,0]));});}
function gotoGame(i){const index=toInt(i,0,session.showSnapshot.games.length-1);return mutate(()=>{session.gameIndex=index;session.phase='lobby';session.questionIndex=0;session.questionToken=uid();session.revealed=false;session.roundMessage='';session.gameScores=Object.fromEntries(session.showSnapshot.teams.map(t=>[t.id,0]));});}
function getInput(id){return document.getElementById(id)?.value??'';}
function copyStr(text){navigator.clipboard?.writeText(text).then(()=>inform('Link kopiert')).catch(()=>window.prompt('Link kopieren:',text));}
async function importFile(file){const data=JSON.parse(await file.text());if(data?.showSnapshot&&data?.scoreboard&&data?.gameIndex!==undefined){const restored=clone(data);restored.id=uid().slice(0,8).toUpperCase();restored.showSnapshot=normalizeShow(restored.showSnapshot);restored.history=[];restored.updated=Date.now();localStorage.setItem('showstudio:v1:session:'+restored.id,JSON.stringify(restored));view='sessions';render();inform('Spielstand importiert – unter „Spielstände“ fortsetzen.');return;}if(data?.show&&data?.questions?.questions){const imported=fromMalagaBackup(data);upsertShow(imported);openShow(imported.id);inform('MÁLAGA-GAMES-Fragen importiert (ohne alten Spielstand).');return;}
 const arr=Array.isArray(data?.shows)?data.shows:Array.isArray(data)?data:[data?.show||data];const cleaned=arr.map(normalizeShow).map(s=>({...s,id:uid()}));cleaned.forEach(upsertShow);openShow(cleaned[0].id);inform(cleaned.length+' Show(s) importiert.');}
function showMenu(id){const s=shows.find(x=>x.id===id);if(!s)return;const action=prompt(`Show: ${s.name}\n\n1 = Duplizieren\n2 = JSON exportieren\n3 = Löschen`,'1');if(action==='1'){const c=clone(s);c.id=uid();c.name+=' · Kopie';upsertShow(c);render();}if(action==='2')download('showstudio-'+s.id+'.json',JSON.stringify(s,null,2));if(action==='3'&&confirm('Diese Show-Vorlage wirklich löschen?')){shows=shows.filter(x=>x.id!==id);saveShows();showId=shows[0]?.id;render();}}
async function addModule(type){const s=currentShow(),g=newGame(type,s.games.length);s.games.push(g);upsertShow(s);editorGameId=g.id;view='builder';builderTab='builder-games';render();}
function displayResponse(raw){const text=decodeURIComponent(raw||'');mutate(()=>{session.roundMessage=text.slice(0,300)});}
async function judgeEstimate(){const g=activeGame(),real=Number(getInput('estimate-correct')),scale=Number(g.estimateTolerance)||1;const guesses=session.showSnapshot.teams.map(t=>({id:t.id,value:Number(getInput('estimate-'+t.id))}));if(!Number.isFinite(real)||guesses.some(v=>!Number.isFinite(v.value))||getInput('estimate-correct').trim()===''||guesses.some(v=>getInput('estimate-'+v.id).trim()===''))throw Error('Bitte den richtigen Wert und alle Schätzungen eintragen.');const sorted=guesses.map(t=>({...t,diff:Math.abs(t.value-real)})).sort((a,b)=>a.diff-b.diff);const lowest=sorted[0].diff,leaders=sorted.filter(x=>Math.abs(x.diff-lowest)<1e-8);record();for(const t of leaders){session.gameScores[t.id]=(session.gameScores[t.id]||0)+g.correctPoints;const mode=g.scoreMode==='inherit'?session.showSnapshot.settings.scoreMode:g.scoreMode;if(mode==='direct'||mode==='mixed')session.scoreboard[t.id].points+=g.correctPoints;}
 session.roundMessage=`Lösung ${real}. ${sorted.map(v=>`${teamName(v.id,session.showSnapshot)}: ${v.value} (±${v.diff.toFixed(2)}, ${Math.ceil(v.diff/scale)} Stufen)`).join(' · ')}`;await persist();}
async function judgeWagers(){const g=activeGame(),key=String(question()?.answer||'A').trim().toUpperCase(),answerIndex='ABCD'.indexOf(key);if(answerIndex<0)throw Error('Für die Risikorunde muss die Lösung A, B, C oder D sein.');const scores={};for(const t of session.showSnapshot.teams){const available=session.banks?.[t.id]??0,arr=[0,1,2,3].map(i=>toInt(getInput('wager-'+t.id+'-'+i)));if(arr.reduce((a,b)=>a+b,0)!==available)throw Error(`${t.name}: Bitte exakt ${available} Einsatzpunkte auf A–D verteilen.`);scores[t.id]=arr[answerIndex];}record();session.banks=scores;session.revealed=true;session.roundMessage='Einsatzpunkte nach Auflösung: '+session.showSnapshot.teams.map(t=>`${t.name} ${scores[t.id]}`).join(' · ');const alive=Object.entries(scores).filter(([,v])=>v>0);if(alive.length===1){await persist();await finishGame(alive[0][0]);return;}if(alive.length===0){await persist();await finishGame(null);return;}await persist();}
function toggleCollection(teamId,cat){mutate(()=>{session.collected ||= {};const have=new Set(session.collected[teamId]||[]);have.has(cat)?have.delete(cat):have.add(cat);session.collected[teamId]=[...have];session.roundMessage=teamName(teamId,session.showSnapshot)+' hat '+have.size+' von '+activeGame().collectionNames.length+' Karten.';});}
async function handleAction(el){const action=el.dataset.act,id=el.dataset.id,team=el.dataset.team;
 try{
 if(action==='dashboard'){view='dashboard';session=null;history.replaceState({},'',location.pathname);return render()}
 if(action==='legacy')return window.open('https://dragonkeks.github.io/malaga-games/','_blank','noopener');
 if(action==='nav'){view=el.dataset.target;return render()}
 if(action==='create'){const name=prompt('Wie soll deine neue Show heißen?','Meine große Gameshow');if(name===null)return;const s=createShow(name.trim()||'Meine Gameshow');upsertShow(s);return openShow(s.id)}
 if(action==='edit-show')return openShow(id);
 if(action==='show-menu')return showMenu(id);
 if(action==='start-choice'){if(id)showId=id;view='start-choice';return render()}
 if(action==='tab'){builderTab=el.dataset.target;return render()}
 if(action==='game-edit'){editorGameId=id;builderTab='builder-games';view='builder';return render()}
 if(action==='builder-games-back'){view='builder';builderTab='builder-games';return render()}
 if(action==='game-move'){const s=currentShow(),i=s.games.findIndex(g=>g.id===id),j=i+Number(el.dataset.dir);if(i<0||j<0||j>=s.games.length)return;[s.games[i],s.games[j]]=[s.games[j],s.games[i]];upsertShow(s);return render()}
 if(action==='add-game-menu'){view='add-game';return render()}
 if(action==='add-module')return addModule(el.dataset.type);
 if(action==='quick-module'){view='builder';showId=currentShow().id;builderTab='builder-games';return addModule(el.dataset.type)}
 if(action==='game-remove'){if(!confirm('Spiel wirklich löschen?'))return;const s=currentShow();s.games=s.games.filter(g=>g.id!==id);editorGameId=null;upsertShow(s);return render()}
 if(action==='question-add'){const s=currentShow(),g=s.games.find(g=>g.id===id);g.questions.push({id:uid(),text:'',answer:'',options:g.type==='choice'||g.type==='wager'?['A','B','C','D']:[],mediaType:'',mediaUrl:''});upsertShow(s);return render()}
 if(action==='question-delete'){const s=currentShow(),g=s.games.find(g=>g.id===editorGameId);if(!confirm('Frage entfernen?'))return;g.questions=g.questions.filter(q=>q.id!==el.dataset.q);upsertShow(s);return render()}
 if(action==='theme-set'){const s=currentShow();s.theme=id;upsertShow(s);return render()}
 if(action==='team-add'){const s=currentShow();if(s.teams.length>=6)throw Error('Maximal sechs Teams.');s.teams.push({id:uid(),name:'Team '+(s.teams.length+1),color:THEMES[s.teams.length%THEMES.length].primary});upsertShow(s);return render()}
 if(action==='team-remove'){const s=currentShow();if(s.teams.length<=2)return;s.teams=s.teams.filter(t=>t.id!==id);upsertShow(s);return render()}
 if(action==='export-show')return download('showstudio-'+currentShow().id+'.json',JSON.stringify(currentShow(),null,2));
 if(action==='export-all')return download('showstudio-alle-shows.json',JSON.stringify({shows},null,2));
 if(action==='duplicate'){const s=clone(currentShow());s.id=uid();s.name+=' · Kopie';upsertShow(s);return openShow(s.id)}
 if(action==='import-click')return $('#import-json')?.click();
 if(action==='start-local')return await beginSession('local');
 if(action==='start-cloud'){if(!hasCloudConfig())throw Error('Firebase-Konfiguration fehlt. Bitte zuerst firebase-config.js einrichten.');view='login';lastAction='start';return render()}
 if(action==='cloud-login-view'){view='login';lastAction='settings';return render()}
 if(action==='cloud-login'){
  const mail=getInput('auth-email').trim(),pass=getInput('auth-password');if(!mail||!pass)throw Error('Bitte E-Mail und Passwort eingeben.');loading=true;cloudUser=await cloudLogin(mail,pass);loading=false;inform('Moderator angemeldet.');if(lastAction==='start')return await beginSession('cloud');if(lastAction==='resume'){await connectSession(sessionId,'cloud','host');view='host';return render();}view='settings';return render();
 }
 if(action==='cloud-save-all'){if(!hasCloudConfig())throw Error('Firebase zuerst konfigurieren.');for(const s of shows)await saveCloudTemplate(s);return inform('Alle Vorlagen in Firebase gesichert.');}
 if(action==='cloud-load-all'){const arr=await loadCloudTemplates();for(const s of arr)upsertShow(normalizeShow(s));inform(arr.length+' Cloud-Vorlagen geladen.');return render()}
 if(action==='resume-session'){sessionMode='local';sessionId=id;view='host';await connectSession(id,'local','host');history.replaceState({},'',`?view=host&session=${id}&mode=local`);return render()}
 if(action==='delete-session'){if(!confirm('Diesen lokalen Spielstand entfernen?'))return;localStorage.removeItem('showstudio:v1:session:'+id);return render()}
 if(action==='cloud-resume'||action==='cloud-tv'){const rid=getInput('cloud-room').trim().replace(/[^A-Za-z0-9_-]/g,'');if(!rid)throw Error('Bitte Show-ID eingeben.');if(action==='cloud-tv')return window.open(`${location.origin}${location.pathname}?view=tv&session=${rid}&mode=cloud`,'_blank');sessionId=rid;view='login';lastAction='resume';return render()}
 if(action==='tv-open')return window.open(link('tv'),'_blank','noopener');
 if(action==='player-link')return copyStr(link('player'));
 if(action==='copy-tv')return copyStr(link('tv'));
 if(action==='copy-player')return copyStr(link('player'));
 if(action==='open-host'){view='host';return render()}
 if(action==='session-export')return download('showstudio-spielstand-'+session.id+'.json',JSON.stringify(session,null,2));
 if(action==='undo'){if(!session?.history?.length)return inform('Keine Änderung zum Zurücknehmen.');const last=session.history.pop(),keep=session.history;session={...last,history:keep};return await persist()}
 if(action==='start-game')return await startGame();
 if(action==='goto-game')return await gotoGame(Number(el.dataset.index));
 if(action==='next-game')return await advanceGame();
 if(action==='next-question')return await nextQuestion();
 if(action==='reveal')return await mutate(()=>{session.revealed=!session.revealed;session.buzzOpen=false;session.entryOpen=false;});
 if(action==='buzz-toggle')return await mutate(()=>{session.buzzOpen=!session.buzzOpen;});
 if(action==='entry-toggle')return await mutate(()=>{session.entryOpen=!session.entryOpen;});
 if(action==='buzz-clear'){buzz=null;await bridge.clearBuzz();return render()}
 if(action==='answers-clear'){answers={};await bridge.clearAnswers();return render()}
 if(action==='response-display')return displayResponse(el.dataset.value);
 if(action==='score-correct')return await valueScore(team,activeGame()?.correctPoints||1,'correct');
 if(action==='score-wrong')return await valueScore(team,-(activeGame()?.wrongPoints||0));
 if(action==='score-plus')return await valueScore(team,1);
 if(action==='score-minus')return await valueScore(team,-1);
 if(action==='coin-plus')return await mutate(()=>{session.scoreboard[team].coins++});
 if(action==='game-win')return await finishGame(team);
 if(action==='game-draw')return await finishGame(null);
 if(action==='game-cancel'){if(!confirm('Spiel ohne Punkte abbrechen?'))return;return await finishGame(null)}
 if(action==='estimate-score')return await judgeEstimate();
 if(action==='collection-toggle')return toggleCollection(team,el.dataset.category);
 if(action==='wager-score')return await judgeWagers();
 if(action==='player-join'){const name=getInput('join-name').trim(),teamId=getInput('join-team');if(!name)throw Error('Bitte Namen eingeben.');if(!teamId)throw Error('Bitte Team auswählen.');playerId=await bridge.join(name,teamId);playerName=name;playerTeam=teamId;localStorage.setItem('showstudio:player:'+sessionId,JSON.stringify({name,teamId,playerId}));inform('Du bist dabei!');return render()}
 if(action==='player-buzz'){if(!playerId)throw Error('Bitte zuerst beitreten.');if(!publicForView()?.buzzOpen)return;const ok=await bridge.buzz(playerId,playerTeam,playerName);inform(ok?'⚡ Du hast zuerst gebuzzert!':'Jemand war schneller!');return;}
 if(action==='player-option'){if(!playerId)return;await bridge.answer(playerId,el.dataset.value,publicForView().questionToken,playerTeam);inform('Antwort gesendet: '+el.dataset.value);return;}
 if(action==='player-send'){const ans=getInput('player-answer').trim();if(!ans)throw Error('Bitte eine Antwort eingeben.');await bridge.answer(playerId,ans,publicForView().questionToken,playerTeam);playerDraftAnswer='';inform('Antwort an die Regie gesendet.');return;}
 }catch(e){loading=false;flashError(e)}
}
const builderChanges={
 'show-name':(s,v)=>s.name=v.slice(0,100),'show-subtitle':(s,v)=>s.subtitle=v.slice(0,180),
 'score-mode':(s,v)=>s.settings.scoreMode=v,'coins-mode':(s,v)=>s.settings.coinsEnabled=v==='yes','participants-mode':(s,v)=>s.settings.participants=v,
 'game-title':(s,v,g)=>g.title=v.slice(0,100),'game-description':(s,v,g)=>g.description=v.slice(0,500),
 'game-type':(s,v,g)=>g.type=v,'game-scoremode':(s,v,g)=>g.scoreMode=v,'game-answer':(s,v,g)=>g.answerMode=v,
 'game-winpoints':(s,v,g)=>g.winPoints=toInt(v,0,9999),'game-correct':(s,v,g)=>g.correctPoints=toInt(v,0,9999),'game-wrong':(s,v,g)=>g.wrongPoints=toInt(v,0,9999),
 'game-coin-correct':(s,v,g)=>g.coinCorrect=toInt(v,0,9999),'game-coin-win':(s,v,g)=>g.coinWin=toInt(v,0,9999),
 'game-seconds':(s,v,g)=>g.seconds=toInt(v,0,3600),'game-tolerance':(s,v,g)=>g.estimateTolerance=Math.max(.001,Number(v)||1),
 'game-wagerbonus':(s,v,g)=>g.wagerBonus=toInt(v,0,9999),'game-collections':(s,v,g)=>g.collectionNames=v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,24),
};
function handleChange(el){if(VIEW!=='host'||view!=='builder')return;const s=currentShow(),g=s.games.find(x=>x.id===editorGameId),id=el.id,v=el.type==='checkbox'?el.checked:el.value;if(builderChanges[id]){builderChanges[id](s,v,g);upsertShow(s);return renderPreserved();}
 if(id==='game-show-responses'){g.showResponses=!!v;upsertShow(s);return renderPreserved();}
 const tname=id.match(/^team-name-(.+)$/),tcolor=id.match(/^team-color-(.+)$/);if(tname||tcolor){const t=s.teams.find(t=>t.id===(tname||tcolor)[1]);if(!t)return;if(tname)t.name=v.slice(0,60);else t.color=v;upsertShow(s);return renderPreserved()}
 const qmatch=id.match(/^q-(text|answer|options|media-type|media)-(.+)$/);if(qmatch){const q=g?.questions.find(x=>x.id===qmatch[2]);if(!q)return;const prop=qmatch[1];if(prop==='text')q.text=v;else if(prop==='answer')q.answer=v;else if(prop==='options')q.options=v.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,6);else if(prop==='media-type')q.mediaType=v;else if(prop==='media')q.mediaUrl=safeUrl(v);upsertShow(s);return renderPreserved()}}
function renderPreserved(){const y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo(0,y));}
root.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el||el.disabled)return;handleAction(el);});
root.addEventListener('change',e=>handleChange(e.target));
root.addEventListener('input',e=>{const el=e.target;if(!el?.id)return;if(el.id==='join-name')playerDraftName=el.value;if(el.id==='player-answer')playerDraftAnswer=el.value;if(el.id.startsWith('estimate-')||el.id.startsWith('wager-'))uiDraft[el.id]=el.value;});
root.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='player-answer'){e.preventDefault();$('#app [data-act="player-send"]')?.click();}});
const fileInput=document.createElement('input');fileInput.id='import-json';fileInput.type='file';fileInput.accept='.json,application/json';fileInput.hidden=true;document.body.append(fileInput);
fileInput.addEventListener('change',async()=>{if(!fileInput.files?.[0])return;try{await importFile(fileInput.files[0]);}catch(ex){flashError(ex)}fileInput.value='';});
async function initialize(){if(VIEW==='host'&&sessionId){view='host';try{if(sessionMode==='cloud'){view='login';lastAction='resume';}else await connectSession(sessionId,'local','host');}catch(ex){flashError(ex)}}
 else if(VIEW==='tv'||VIEW==='player'){
  const saved=getJSON('showstudio:player:'+sessionId,null);if(saved){playerId=saved.playerId;playerName=saved.name;playerTeam=saved.teamId;}
  if(sessionId){try{await connectSession(sessionId,sessionMode,VIEW)}catch(ex){flashError(ex)}}else error='Keine Show-ID übergeben.';
 }
 render();}
initialize();
